const body = $('Event Registration Webhook').first().json.body || {};
const data = body.data || {};
const required = ['eventId', 'name', 'phone'];
const missing = required.filter((key) => !String(data[key] || '').trim());
if (missing.length) {
  return [{ json: { ok: false, statusCode: 400, message: `蝻箏?敹?甈?嚗?{missing.join(', ')}` } }];
}
const companions = Number(data.companions || 0);
if (!Number.isFinite(companions) || companions < 0) {
  return [{ json: { ok: false, statusCode: 400, message: '??鈭箸?澆??航炊' } }];
}
return [{ json: {
  ok: true,
  eventId: String(data.eventId).trim(),
  name: String(data.name).trim(),
  phone: String(data.phone).trim(),
  companions,
  note: String(data.note || '').trim(),
  lineUserId: String(data.lineUserId || '').trim(),
  lineDisplayName: String(data.lineDisplayName || '').trim(),
  liffLanguage: String(data.liffLanguage || '').trim(),
  liffOS: String(data.liffOS || '').trim(),
  isInClient: Boolean(data.isInClient),
  submittedAt: body.submittedAt || new Date().toISOString()
} }];

const input = $('Validate Payload').first().json;
if (!input.ok) return [{ json: input }];
function textFromValue(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(textFromValue).filter(Boolean).join(',');
  if (value.name) return String(value.name);
  if (value.plain_text) return String(value.plain_text);
  if (value.title) return textFromValue(value.title);
  if (value.rich_text) return textFromValue(value.rich_text);
  if (value.select) return textFromValue(value.select);
  if (value.multi_select) return textFromValue(value.multi_select);
  if (value.date) return value.date.start || '';
  if (value.checkbox != null) return String(value.checkbox);
  if (value.number != null) return String(value.number);
  if (value.url) return String(value.url);
  return '';
}
function prop(json, names) {
  const wanted = Array.isArray(names) ? names : [names];
  for (const name of wanted) {
    if (json[name] != null) return textFromValue(json[name]).trim();
    const p = json.properties?.[name];
    if (p != null) return textFromValue(p).trim();
  }
  const props = json.properties || {};
  for (const [key, value] of Object.entries(props)) {
    if (wanted.some((name) => key.trim() === name || key.includes(name))) return textFromValue(value).trim();
  }
  return '';
}
const events = $('Query Events').all();
const event = events.find((item) => item.json.id === input.eventId);
if (!event) {
  return [{ json: { ok: false, statusCode: 404, message: '找不到活動，請確認報名網址是否正確。' } }];
}
const eventJson = event.json;
const title = prop(eventJson, ['活動主題', 'title', 'Name']);
const enabledRaw = prop(eventJson, ['報名表單', 'registrationEnabled']);
const enabled = ['true', '開放報名', '開放', 'yes', '1'].includes(String(enabledRaw).toLowerCase()) || enabledRaw === '';
if (!enabled) {
  return [{ json: { ok: false, statusCode: 409, message: '甇斗暑??開放報名' } }];
}
const deadline = prop(eventJson, ['報名截止時間', 'registrationDeadline']);
if (deadline && new Date(deadline).getTime() < Date.now()) {
  return [{ json: { ok: false, statusCode: 409, message: '活動報名已截止。' } }];
}
const limit = Number(prop(eventJson, ['報名名額上限', 'registrationLimit']) || 0);
const registrations = $('Query Existing Registrations').all();
const active = registrations.filter((item) => {
  const eventId = prop(item.json, ['瘣餃?ID', 'eventId']);
  const status = prop(item.json, ['狀態, 'status']);
  return eventId === input.eventId && status !== 'cancelled';
});
if (input.lineUserId) {
  const duplicate = active.find((item) => prop(item.json, ['LINE User ID', 'LINE userId']) === input.lineUserId);
  if (duplicate) {
    return [{ json: { ok: false, statusCode: 409, message: '你已完成報名，請勿重複報名。' } }];
  }
}
if (limit > 0 && active.length >= limit) {
  return [{ json: { ok: false, statusCode: 409, message: '活動名額已滿。 } }];
}
const date = new Date();
const y = date.getFullYear();
const m = String(date.getMonth() + 1).padStart(2, '0');
const d = String(date.getDate()).padStart(2, '0');
const serial = String(active.length + 1).padStart(3, '0');
return [{ json: { ...input, eventTitle: title, registrationId: `REG-${y}${m}${d}-${serial}`, status: 'registered', createdAt: new Date().toISOString() } }];
